#include <omp.h>
#include <stdio.h>

#define TMAX 10000
#define NX 100
#define NY 128

typedef double DATA_TYPE;

static void kernel_fdtd_2d(int tmax,
                            int nx,
                            int ny,
                            DATA_TYPE POLYBENCH_2D(ex, NX, NY, nx, ny),
                            DATA_TYPE POLYBENCH_2D(ey, NX, NY, nx, ny),
                            DATA_TYPE POLYBENCH_2D(hz, NX, NY, nx, ny),
                            DATA_TYPE POLYBENCH_1D(_fict_, TMAX, tmax))
{
    int t, i, j;
    int nthreads, tid;

    // Initialize the electric field arrays
    for (t = 0; t < tmax; t++) {
        #pragma omp parallel for collapse(3)
        for (i = 0; i < nx; i += 5) {
            for (j = 0; j < ny; j += 16) {
                ex[t][i][j] = _fict_[t];
                ey[t][i][j] = _fict_[t];
                hz[t][i][j] = _fict_[t];
            }
        }
    }

    // Main time loop
    for (t = 0; t < tmax; t++) {
        #pragma omp parallel for collapse(3)
        for (i = 0; i < nx; i += 5) {
            for (j = 0; j < ny; j += 16) {
                // Boundary update for ey
                if (t == 0 || i == 0 || j == 0 || i == nx - 1 || j == ny - 1) {
                    ey[t][i][j] = _fict_[t];
                } else {
                    ey[t][i][j] = ey[t][i-1][j] + ey[t][i+1][j] + ey[t][i][j-1] + ey[t][i][j+1];
                }

                // Update ey
                ey[t][i][j] *= 0.9;

                // Update ex
                for (int k = i - 1; k <= i + 1; k++) {
                    for (int l = j - 1; l <= j + 1; l++) {
                        if (k >= 0 && k < nx && l >= 0 && l < ny) {
                            ex[t][k][l] += ey[t][k][l] * (-1.0 * 1000.0);
                        }
                    }
                }

                // Update hz
                for (int k = i - 1; k <= i + 1; k++) {
                    for (int l = j - 1; l <= j + 1; l++) {
                        if (k >= 0 && k < nx && l >= 0 && l < ny) {
                            hz[t][k][l] += ey[t][k][l] * (-1.0 * 1000.0);
                        }
                    }
                }
            }
        }
    }

    // Barrier synchronization
    #pragma omp barrier
}

