#define EPSILON 0.1f

void kernel_correlation(int m, int n, float *data, float *symmat, float *mean, float *stddev) {
    int i, j, k;
    float sum, temp;

    // Mean calculation
    #pragma omp parallel for reduction(+: mean)
    for (i = 0; i < m; i++) {
        sum = 0.0f;
        for (j = 0; j < n; j++) {
            sum += data[i*n+j];
        }
        mean[i] = sum / n;
    }

    // Standard deviation calculation
    #pragma omp parallel for reduction(+: stddev)
    for (i = 0; i < m; i++) {
        sum = 0.0f;
        for (j = 0; j < n; j++) {
            sum += (data[i*n+j] - mean[i]) * (data[i*n+j] - mean[i]);
        }
        stddev[i] = sqrt(sum / (n - EPSILON)) / sqrt(n);
    }

    // Centering and reducing data
    #pragma omp parallel for collapse(2)
    for (i = 0; i < m; i++) {
        for (j = i; j < m; j++) {
            sum = 0.0f;
            for (k = 0; k < n; k++) {
                sum += (data[i*n+k] - mean[i]) * (data[j*n+k] - mean[j]);
            }
            symmat[i*m+j] = sum / (stddev[i]*stddev[j]);
        }
    }

    // Diagonal elements setting to 1.0
    for (i = 0; i < m; i++) {
        symmat[i*m+i] = 1.0f;
    }
}

