        }

        p[i] = 1.0 / sqrt(x);

        #pragma omp parallel for reduction(+: A[i][i]) reduction(min(*A[i][i], 0.0))
        for (j = i + 1; j < N; ++j) {
            x = A[i][j];
            for (k = 0; k <= i - 1; ++k) {
                x -= A[i][k] * A[j][k];
            }
            A[j][i] = x * p[i];
        }
    }
