static void kernel_ludcmp(int n, DATA_TYPE POLYBENCH_2D(A, N+1, N+1, n+1, n+1), DATA_TYPE POLYBENCH_1D(b, N+1, n+1), DATA_TYPE POLYBENCH_1D(x, N+1, n+1), DATA_TYPE POLYBENCH_1D(y, N+1, n+1)) {
    int i, j, k;
    DATA_TYPE w;

    // Initialize b to 1.0
    b[0] = 1.0;

    // Parallelize the outer loop over rows
    #pragma omp parallel for collapse(2) private(w)
    for (i = 0; i < n; i++) {
        for (j = 0; j <= i; j++) {
            w = A[j][i];
            for (k = 0; k < j; k++) {
                w -= A[k][i] * A[j][k];
            }
            A[j][i] = w;
        }
        #pragma omp barrier
    }

    // Update the first half of A
    for (i = 1; i < n; i++) {
        for (j = 0; j < i; j++) {
            w = A[i][j];
            for (k = 0; k < j; k++) {
                w -= A[k][j] * A[i][k];
            }
            A[i][j] = w;
        }
    }

    // Solve for y
    y[0] = b[0];
    for (i = 1; i < n; i++) {
        y[i] = b[i] - A[i][0] * y[0];
    }

    // Back substitution
    x[n-1] = y[n-1] / A[n-1][n-1];
    for (i = n-2; i >= 0; i--) {
        x[i] = y[i] - A[i][i] * x[i+1];
    }
}

